shell_commands:
node -e "
const fs = require('fs');
const path = require('path');
const pkg = path.dirname(require.resolve('@re-cinq/eslint-plugin-re-lint/package.json'));
const walk = d => fs.readdirSync(d, {withFileTypes: true}).flatMap(e => e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)]);
console.log(walk(pkg).map(p => path.relative(pkg, p)).join('\n'));
"

node -e "
const fs = require('fs');
const path = require('path');
const pkg = './node_modules/@re-cinq/eslint-plugin-re-lint';
const walk = d => fs.readdirSync(d, {withFileTypes: true}).flatMap(e => e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)]);
const files = walk(pkg);
for (const f of files) {
  if (/require-spec-link|require-colocated-tests|test-imports-its-subject|require-status-matches-coverage|max-expects/.test(f)) {
    console.log('=== ' + f + ' ===');
    console.log(fs.readFileSync(f, 'utf8'));
  }
}
"

